/* @autogenerated */
package net.civeira.phylax.common.infrastructure.mail;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.doThrow;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.timeout;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Optional;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import org.mockito.ArgumentCaptor;

import io.quarkus.mailer.Mail;
import io.quarkus.mailer.Mailer;
import io.vertx.ext.mail.MailMessage;
import io.vertx.mutiny.ext.mail.MailClient;
import jakarta.activation.DataSource;

@DisplayName("EmailService")
class EmailServiceUnitTest {

  @TempDir
  Path temp;

  private Mailer mailer;
  private DynamicMailClientCache cache;
  private MailClient client;
  private EmailService service;

  @BeforeEach
  void setUp() {
    mailer = mock(Mailer.class);
    cache = mock(DynamicMailClientCache.class);
    client = mock(MailClient.class);
    when(cache.clientFor(any())).thenReturn(client);
    service = new EmailService(mailer, cache);
  }

  private static EmailMessage message(String content, String html) {
    return EmailMessage.builder().targetName("Ana").targetAddress("ana@example.com").subject("Hi")
        .content(content).htmlContent(html).build();
  }

  /** A message whose contents may be null, which the builder does not allow. */
  private static EmailMessage loose(String content, String html) {
    EmailMessage message = mock(EmailMessage.class);
    when(message.getTargetName()).thenReturn("Ana");
    when(message.getTargetAddress()).thenReturn("ana@example.com");
    when(message.getSubject()).thenReturn("Hi");
    when(message.getContent()).thenReturn(content);
    when(message.getHtmlContent()).thenReturn(html);
    when(message.getEmbbeds()).thenReturn(List.of());
    when(message.getAttacheds()).thenReturn(List.of());
    when(message.getSentObserver()).thenReturn(Optional.empty());
    when(message.getFailObserver()).thenReturn(Optional.empty());
    return message;
  }

  private Mail sentMail() {
    ArgumentCaptor<Mail> mail = ArgumentCaptor.forClass(Mail.class);
    verify(mailer).send(mail.capture());
    return mail.getValue();
  }

  private MailMessage sentDynamic() {
    ArgumentCaptor<MailMessage> mail = ArgumentCaptor.forClass(MailMessage.class);
    verify(client).sendMailAndAwait(mail.capture());
    return mail.getValue();
  }

  @Nested
  @DisplayName("Default mailer")
  class DefaultMailer {

    @Test
    @DisplayName("Should send html with its text alternative and notify the observer")
    void shouldSendHtmlWithText() {
      MailSent sent = mock(MailSent.class);
      EmailMessage message =
          EmailMessage.builder().targetName("Ana").targetAddress("ana@example.com").subject("Hi")
              .content("text").htmlContent("<p>x</p>").sentObserver(sent).build();

      service.sendMessage(message);

      Mail mail = sentMail();
      assertEquals(List.of("Ana <ana@example.com>"), mail.getTo());
      assertEquals("<p>x</p>", mail.getHtml());
      assertEquals("text", mail.getText());
      verify(sent).ok();
    }

    @Test
    @DisplayName("Should use the html as text when there is no text content")
    void shouldUseHtmlAsText() {
      service.sendMessages(loose(null, "<p>x</p>"));

      assertEquals("<p>x</p>", sentMail().getText());
    }

    @Test
    @DisplayName("Should send plain text when there is no html content")
    void shouldSendPlainText() {
      service.sendMessage(loose("text", null));

      Mail mail = sentMail();
      assertEquals("text", mail.getText());
      assertNull(mail.getHtml());
    }

    @Test
    @DisplayName("Should attach and embed files and data sources")
    void shouldAttachFilesAndDataSources() throws IOException {
      // Arrange — file and data source attachments, both embedded and attached
      File file = Files.writeString(temp.resolve("doc.txt"), "doc").toFile();
      DataSource source = mock(DataSource.class);
      when(source.getName()).thenReturn("data.bin");
      when(source.getContentType()).thenReturn("application/octet-stream");
      when(source.getInputStream())
          .thenAnswer(_ -> new ByteArrayInputStream("data".getBytes(StandardCharsets.UTF_8)));
      DataSource broken = mock(DataSource.class);
      when(broken.getName()).thenReturn("broken.bin");
      when(broken.getInputStream()).thenThrow(new IOException("gone"));
      EmailMessage message = EmailMessage.builder().targetName("Ana")
          .targetAddress("ana@example.com").subject("Hi").content("text").htmlContent("<p>x</p>")
          .embbeds(List.of(new Attach("logo", file), new Attach("pic", source)))
          .attacheds(List.of(new Attach("doc", file), new Attach("data", source),
              new Attach("broken", broken)))
          .build();

      // Act — send the message
      service.sendMessage(message);

      // Assert — the readable attachments are included, the broken one is skipped
      Mail mail = sentMail();
      assertEquals(4, mail.getAttachments().size());
      assertEquals(2, mail.getAttachments().stream().filter(a -> a.isInlineAttachment()).count());
    }

    @Test
    @DisplayName("Should notify the failure observer when sending fails")
    void shouldNotifyFailure() {
      MailFail fail = mock(MailFail.class);
      RuntimeException error = new RuntimeException("smtp down");
      doThrow(error).when(mailer).send(any(Mail.class));
      EmailMessage message =
          EmailMessage.builder().targetName("Ana").targetAddress("ana@example.com").subject("Hi")
              .content("text").htmlContent("<p>x</p>").failObserver(fail).build();

      service.sendMessage(message);

      verify(fail).fail(error);
    }

    @Test
    @DisplayName("Should swallow failures without a failure observer")
    void shouldSwallowFailureWithoutObserver() {
      doThrow(new RuntimeException("smtp down")).when(mailer).send(any(Mail.class));

      service.sendMessage(message("text", "<p>x</p>"));

      verify(mailer).send(any(Mail.class));
    }
  }

  @Nested
  @DisplayName("Dynamic client")
  class DynamicClient {

    @Test
    @DisplayName("Should send from the configured name and address")
    void shouldSendFromNameAndAddress() {
      MailConfiguration config =
          MailConfiguration.builder().fromName("Phylax").fromEmail("no-reply@phylax").build();

      service.sendMessage(config, message("text", "<p>x</p>"));

      MailMessage mail = sentDynamic();
      assertEquals("Phylax <no-reply@phylax>", mail.getFrom());
      assertEquals("<p>x</p>", mail.getHtml());
      assertEquals("text", mail.getText());
      verify(mailer, never()).send(any(Mail.class));
    }

    @Test
    @DisplayName("Should send from the bare address and fall back to html as text")
    void shouldSendFromAddressOnly() {
      MailConfiguration config = MailConfiguration.builder().fromEmail("no-reply@phylax").build();

      service.sendMessages(config, loose(null, "<p>x</p>"));

      MailMessage mail = sentDynamic();
      assertEquals("no-reply@phylax", mail.getFrom());
      assertEquals("<p>x</p>", mail.getText());
    }

    @Test
    @DisplayName("Should send plain text without a sender")
    void shouldSendPlainTextWithoutSender() {
      service.sendMessage(MailConfiguration.builder().build(), loose("text", null));

      MailMessage mail = sentDynamic();
      assertNull(mail.getFrom());
      assertNull(mail.getHtml());
      assertEquals("text", mail.getText());
    }
  }

  @Nested
  @DisplayName("Delayed sending")
  class Delayed {

    @Test
    @DisplayName("Should send in the background with the default mailer")
    void shouldDelayWithDefaultMailer() {
      service.delaySendMessage(message("text", "<p>x</p>"));
      service.delaySendMessages(message("text", "<p>y</p>"));

      verify(mailer, timeout(5000).times(2)).send(any(Mail.class));
    }

    @Test
    @DisplayName("Should send in the background with a dynamic client")
    void shouldDelayWithDynamicClient() {
      MailConfiguration config = MailConfiguration.builder().build();

      service.delaySendMessage(config, message("text", "<p>x</p>"));
      service.delaySendMessages(config, message("text", "<p>y</p>"));

      verify(client, timeout(5000).times(2)).sendMailAndAwait(any(MailMessage.class));
      verify(cache, times(2)).clientFor(config);
    }
  }
}
